#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../mrc-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=262144,repeat=argc>1?atoi(argv[1]):100;float margin=.01f;std::vector<int>y(n);std::vector<float>a(n),b(n),d(n),expected(2*n),got(2*n),output;for(int i=0;i<n;i++){y[i]=i%2?-1:1;a[i]=float((13*i+7)%257-128)/64.f;b[i]=float((37*i+11)%257-128)/64.f;d[i]=float((29*i+3)%257-128)/64.f;if(i<256){y[i]=1;a[i]=margin;b[i]=0;d[i]=.5f;}bool active=-float(y[i])*(a[i]-b[i])+margin>=0;expected[i]=active?-float(y[i])*d[i]:0;expected[n+i]=active?float(y[i])*d[i]:0;}int*dy;float *da,*db,*dd,*o1,*o2;CK(cudaMalloc(&dy,n*4));for(auto p:{&da,&db,&dd,&o1,&o2})CK(cudaMalloc(p,n*4));CK(cudaMemcpy(dy,y.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(da,a.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(db,b.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dd,d.data(),n*4,cudaMemcpyHostToDevice));auto launch=[&](int mode){if(mode==1)MRCGradient<<<n/256,256>>>(n,dy,da,db,dd,margin,o1,o2);else if(mode==2)MRCGradient2<<<n/256,256>>>(n,dy,da,db,dd,margin,o1,o2);else MRCGradient3<<<n/1024,256>>>(n,dy,da,db,dd,margin,o1,o2);};for(int mode=1;mode<=3;mode++)launch(mode);CK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){double times[3]={};float ma=0,mr=0;bool ok=true;output.clear();for(int mode=1;mode<=3;mode++){CK(cudaMemset(o1,255,n*4));CK(cudaMemset(o2,255,n*4));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch(mode);CK(cudaDeviceSynchronize());times[mode-1]=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;CK(cudaMemcpy(got.data(),o1,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(got.data()+n,o2,n*4,cudaMemcpyDeviceToHost));for(int i=0;i<2*n;i++){float e=fabsf(got[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(got[i])&&e<=1e-3f;}output.insert(output.end(),got.begin(),got.end());}all&=ok;char file[100];sprintf(file,"mrc_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_three_MRC_kernel_regions_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"mode_times_seconds\":[%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1]+times[2],ok?"true":"false",int(output.size()),ma,mr,repeat,times[0],times[1],times[2],file,int(output.size()));}CK(cudaFree(dy));for(auto p:{da,db,dd,o1,o2})CK(cudaFree(p));puts(all?"PASS":"FAIL");return all?0:1;}
